export const companySearchEstablishments = defineFunction({
  name: "fod.company_search_establishments",
  connector: "fod",
  class: "read",
  act: false,
  description: "Enumerate French establishments in the SIRENE stock (head offices and branches, active or closed) by cumulative filters, ordered by SIRET: {items: [{siren, siret, nic, is_siege, etat, date_creation, denomination, enseigne_1, naf, tranche_effectifs, annee_effectifs, caractere_employeur, code_postal, libelle_commune, code_commune, ...}], count, limit, offset}. Use it for exhaustive lists a search engine caps: every bakery of a department, every site of a brand, head offices of 100 to 499 employees in a department. The company's name is not in this stock: denomination is the establishment's usual name, empty for most; read the names by listing the legal units of the SIRENs. To find a company by its name, use the company search. count equal to limit: more may follow, pass offset + limit. A department or a postal code narrows the scan to one part of the stock; without one the scan reads all of France and may be stopped. In French: liste d'établissements, sites d'une enseigne.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "anyOf": [
      {"required": ["naf"]},
      {"required": ["code_commune"]},
      {"required": ["code_postal"]},
      {"required": ["departement"]},
      {"required": ["denomination"]},
      {"required": ["enseigne"]}
    ],
    "properties": {
      "naf": {
        "type": "string",
        "pattern": "^[0-9]{2}\\.?[0-9]{2}[A-Z]$",
        "description": "Main activity code of the establishment (NAF rev. 2), with or without the dot: 47.11F or 4711F."
      },
      "code_commune": {
        "type": "string",
        "pattern": "^([0-9]{2}|2A|2B)[0-9]{3}$",
        "description": "INSEE code of the establishment's commune; Paris, Lyon and Marseille by arrondissement (13201, not 13055)."
      },
      "code_postal": {"type": "string", "pattern": "^[0-9]{5}$", "description": "Postal code of the establishment."},
      "departement": {
        "type": "string",
        "pattern": "^([0-9]{2}|97[1-6])$",
        "description": "Start of the establishment's postal code: two digits in mainland France (20 for Corsica, not 2A or 2B), three overseas (971)."
      },
      "denomination": {
        "type": "string",
        "minLength": 2,
        "maxLength": 120,
        "description": "Part of the establishment's usual name, case ignored; rarely filled."
      },
      "enseigne": {
        "type": "string",
        "minLength": 2,
        "maxLength": 120,
        "description": "Part of one of the establishment's signs (enseigne), case ignored: carrefour express."
      },
      "active_only": {"type": "boolean", "default": true, "description": "false also returns closed establishments."},
      "sieges_only": {"type": "boolean", "default": false, "description": "true keeps head offices only."},
      "tranche_effectifs": {
        "type": "array",
        "minItems": 1,
        "items": {
          "type": "string",
          "enum": ["NN", "00", "01", "02", "03", "11", "12", "21", "22", "31", "32", "41", "42", "51", "52", "53"]
        },
        "description": "INSEE headcount bands of the establishment, any of them (00 = none, 01 = 1-2, 11 = 10-19, 21 = 50-99, 22 = 100-199, 31 = 200-249, 32 = 250-499 ... 53 = 10,000 and more)."
      },
      "limit": {"type": "integer", "minimum": 1, "maximum": 1000, "default": 100},
      "offset": {
        "type": "integer",
        "minimum": 0,
        "default": 0,
        "description": "Establishments skipped: the next page is offset + limit."
      }
    }
  },
  examples: [
    { title: "Supermarkets of the Bouches-du-Rhône", input: {"naf": "47.11F", "departement": "13", "limit": 200} },
    { title: "Head offices of 100 to 499 employees in Gironde", input: {"departement": "33", "sieges_only": true, "tranche_effectifs": ["22", "31", "32"]} },
  ],
  refusals: [
    { code: "stock_scan_too_long", when: 504, message: "The scan of the SIRENE stock was stopped after 90 s: narrow it (a department or a postal code, a shorter list) rather than retrying unchanged." },
  ],
  request: {
    method: "POST",
    path: "/api/sirene/search",
    pathParams: [],
    query: {},
    body: {"naf": "naf", "code_commune": "code_commune", "code_postal": "code_postal", "departement": "departement", "denomination": "denomination", "enseigne": "enseigne", "active_only": "active_only", "sieges_only": "sieges_only", "tranche_effectifs": "tranche_effectifs", "limit": "limit", "offset": "offset"},
    headers: {},
  },
  timeoutMs: 150000,
  cost: { per: "request" },
})

