export const urbanStartRegulationIngestion = defineFunction({
  name: "fod.urban_start_regulation_ingestion",
  connector: "fod",
  class: "read",
  act: false,
  description: "Ask FOD to fetch and index the written regulation of a local plan it does not hold yet, from the national town-planning portal (GPU). The work runs in the background, from 20 seconds to a few minutes; the answer comes at once with the state {idurba, statut, message, ...}: en_cours (started, or already running), pret or scanne (already held, nothing restarted), echec (a recent failure, erreur gives the cause; no new attempt before relance_possible_apres). Calling it again never starts a second ingestion. Then read the ingestion state every 20 to 30 seconds until pret, scanne or echec. FOD ingests one regulation at a time: a busy answer asks to retry in a minute. A document replaced on the portal is not swapped for its successor; the refusal names the documents published for the same territory. In French: charger le règlement d'un plu, indexer un règlement d'urbanisme.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "required": ["idurba"],
    "properties": {
      "idurba": {
        "type": "string",
        "pattern": "^[0-9A-Za-z]{5,9}_(PLU|PLUI|PLUi|POS|CC|PSMV)_[0-9]{8}(_[0-9A-Za-z]{1,5})?$",
        "description": "Identifier of the planning document, as zone.idurba of the zoning: 80021_PLU_20251211."
      }
    }
  },
  examples: [
    { title: "Regulation of the Amiens local plan", input: {"idurba": "80021_PLU_20251211"} },
  ],
  refusals: [
    { code: "regulation_not_published", when: 404, message: "The national town-planning portal does not publish this document or its written regulation (a municipal map, carte communale, has none); autres_documents names the documents published for the same territory." },
  ],
  request: {
    method: "POST",
    path: "/api/reglements/{idurba}/ingestion",
    pathParams: ["idurba"],
    query: {},
    body: {},
    headers: {},
  },
  async: { collect: "fod.urban_get_regulation_ingestion", jobId: { from: "idurba", to: "idurba" } },
  cost: { per: "request" },
})

